data.styles:
/* GLOBAL */
html { scroll-behavior: smooth; }
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; color: var(--color-text); line-height: 1.6; background: var(--color-bg); overflow-wrap: break-word; }
h1, h2, h3 { font-weight: 800; line-height: 1.15; letter-spacing: -0.01em; color: var(--color-text); }
a { color: var(--color-link); }
ul, ol { list-style: none; }

/* MENU: the club's two colours as a stripe under it */
.site-nav { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0.5rem 2rem; padding: 0.9rem 2rem; background: var(--color-surface); border-bottom: 4px solid var(--color-marker); position: sticky; top: 0; z-index: 100; }
.nav-logo { font-size: 1.2rem; font-weight: 800; color: var(--color-text); text-decoration: none; }
.nav-links { display: flex; flex-wrap: wrap; gap: 0.25rem 1.75rem; margin-left: auto; }
.nav-links a { color: var(--color-text); text-decoration: none; font-weight: 600; padding: 0.35rem 0; border-bottom: 2px solid transparent; transition: border-color 0.2s; }
.nav-links a:hover { border-bottom-color: var(--color-marker); }

/* BUTTONS */
.btn { display: inline-flex; align-items: center; justify-content: center; min-height: 3rem; padding: 0.6rem 1.6rem; border-radius: 999px; border: 2px solid var(--color-primary); font-weight: 700; text-decoration: none; text-align: center; transition: background 0.2s, color 0.2s, border-color 0.2s; }
.btn-primary { background: var(--color-primary); color: var(--color-on-primary); }
.btn-primary:hover { background: var(--color-primary-strong); border-color: var(--color-primary-strong); }
.btn-ghost { background: transparent; color: var(--color-link); }
.btn-ghost:hover { background: var(--color-primary); color: var(--color-on-primary); }
.nav-join { min-height: 2.5rem; padding: 0.35rem 1.1rem; font-size: 0.95rem; }
.actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* HERO: the name and the buttons beside the path */
.hero { display: flex; flex-wrap: wrap; align-items: center; gap: 2rem 2.5rem; max-width: 72rem; margin: 0 auto; padding: 3.5rem 2rem 4rem; }
.hero-text { flex: 1 1 18rem; }
.hero-photo { flex: 1.4 1 22rem; }
.kicker { color: var(--color-accent); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; margin-bottom: 0.75rem; }
.hero h1 { font-size: clamp(2.1rem, 3.2vw + 1rem, 3.4rem); margin-bottom: 0.9rem; }
.hero-lead { font-size: 1.15rem; color: var(--color-text-muted); max-width: 36rem; margin-bottom: 1.75rem; }

/* SECTIONS */
.section { max-width: 72rem; margin: 0 auto; padding: 4rem 2rem; }
.section h2 { font-size: clamp(1.7rem, 3vw + 0.8rem, 2.4rem); margin-bottom: 0.5rem; }
.section-lead { color: var(--color-text-muted); max-width: 40rem; margin-bottom: 2rem; }
.band { background: var(--color-surface-alt); }

/* THIS WEEK: a walk per line, the day and the hour first */
.sessions li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.15rem 2rem; padding: 1.1rem 0; border-top: 1px solid var(--color-border); }
.sessions li:last-child { border-bottom: 1px solid var(--color-border); }
.session-when { flex: 0 0 11rem; font-weight: 800; color: var(--color-accent); }
.session-name { flex: 1 1 12rem; font-weight: 700; font-size: 1.1rem; }
.session-meta { flex: 2 1 16rem; color: var(--color-text-muted); }

/* COMING UP: a card per date */
.date-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(15rem, 100%), 1fr)); gap: 1.25rem; }
.date-card { background: var(--color-surface); border: 1px solid var(--color-border); border-top: 4px solid var(--color-marker); border-radius: 0.5rem; padding: 1.25rem 1.4rem 1.4rem; }
.date-day { color: var(--color-accent); font-weight: 700; font-size: 0.95rem; margin-bottom: 0.35rem; }
.date-card h3 { font-size: 1.2rem; margin-bottom: 0.35rem; }
.date-card p:last-child { color: var(--color-text-muted); }

/* THE GROUPS */
.group-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr)); gap: 1.5rem 2.5rem; }
.group h3 { font-size: 1.3rem; margin-bottom: 0.35rem; padding-top: 0.85rem; border-top: 4px solid var(--color-primary); }
.group p { color: var(--color-text-muted); }

/* THE COMMITTEE: initials in a round badge, where a portrait goes */
.team-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(13rem, 100%), 1fr)); gap: 1.5rem; }
.member { display: flex; align-items: center; gap: 0.9rem; }
.member-initials { flex: 0 0 auto; display: flex; align-items: center; justify-content: center; width: 3.5rem; height: 3.5rem; border-radius: 50%; background: var(--color-primary); color: var(--color-on-primary); font-weight: 800; letter-spacing: 0.04em; }
.member-name { font-weight: 700; }
.member-role { color: var(--color-text-muted); font-size: 0.95rem; }

/* WORDS BESIDE A PHOTO */
.split { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(19rem, 100%), 1fr)); gap: 2rem 3rem; align-items: center; }
.split p { max-width: 34rem; margin-top: 0.6rem; }
.split a { font-weight: 600; }
.note { color: var(--color-text-muted); font-size: 0.95rem; }

/* PHOTOS: the template's own, each an image an author swaps for theirs; a little dimmer in the dark theme */
.photo { display: block; width: 100%; height: auto; object-fit: cover; border-radius: 0.75rem; filter: brightness(var(--photo-brightness)); }
.hero-photo .photo { aspect-ratio: 16 / 9; }
.split-photo .photo { aspect-ratio: 4 / 3; }

/* THE JOINING BAND */
.join-band { text-align: center; padding: 4rem 2rem; background: var(--color-band-bg); color: var(--color-band-text); }
.join-band h2 { color: var(--color-band-text); font-size: clamp(1.7rem, 3vw + 0.8rem, 2.4rem); margin-bottom: 0.5rem; }
.join-band p { max-width: 34rem; margin: 0 auto 1.75rem; }
.join-band .actions { justify-content: center; }
.join-band .btn { background: var(--color-band-text); color: var(--color-band-bg); border-color: var(--color-band-text); }
.join-band .btn:hover { background: var(--color-marker); border-color: var(--color-marker); color: var(--color-on-marker); }

/* THE JOIN PAGE */
.page-head { max-width: 72rem; margin: 0 auto; padding: 3.5rem 2rem 1rem; }
.page-head h1 { font-size: clamp(2.1rem, 4vw + 1rem, 3.25rem); margin-bottom: 0.5rem; }
.page-head p { color: var(--color-text-muted); max-width: 40rem; }
.fee-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(19rem, 100%), 1fr)); gap: 2rem 3rem; }
.fee-list li { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 0.15rem 1rem; padding: 0.8rem 0; border-top: 1px solid var(--color-border); }
.fee-price { font-weight: 800; font-size: 1.25rem; color: var(--color-accent); }
.dot-list li { position: relative; padding: 0.45rem 0 0.45rem 1.5rem; }
.dot-list li::before { content: ''; position: absolute; left: 0; top: 1rem; width: 0.6rem; height: 0.6rem; border-radius: 50%; background: var(--color-marker); }
.step-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(15rem, 100%), 1fr)); gap: 1.5rem 2.5rem; counter-reset: step; }
.step { counter-increment: step; }
.step::before { content: counter(step); display: flex; align-items: center; justify-content: center; width: 2.5rem; height: 2.5rem; border-radius: 50%; background: var(--color-primary); color: var(--color-on-primary); font-weight: 800; margin-bottom: 0.75rem; }
.step h3 { font-size: 1.2rem; margin-bottom: 0.3rem; }
.step p { color: var(--color-text-muted); }
.faq-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(19rem, 100%), 1fr)); gap: 1.5rem 3rem; margin-bottom: 2rem; }
.faq h3 { font-size: 1.1rem; margin-bottom: 0.3rem; }
.faq p { color: var(--color-text-muted); }

/* FOOTER */
.site-footer { background: var(--color-footer-bg); color: var(--color-footer-text); padding: 2.5rem 2rem 1.25rem; }
.footer-content { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 1.5rem 2rem; max-width: 72rem; margin: 0 auto; }
.footer-logo { font-size: 1.2rem; font-weight: 800; }
.footer-brand p { color: var(--color-footer-muted); font-size: 0.9rem; margin-top: 0.35rem; }
.footer-note { max-width: 72rem; margin: 1.75rem auto 0; padding-top: 1.25rem; border-top: 1px solid rgba(255, 255, 255, 0.12); color: var(--color-footer-muted); font-size: 0.85rem; }

/* LANGUAGE SWITCH (a site in several languages) */
.footer-lang { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem 0.75rem; }
.lang-label { color: var(--color-footer-muted); font-size: 0.9rem; }
.lang-switch { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.lang-btn { color: var(--color-footer-text); text-decoration: none; padding: 0.35rem 0.9rem; border-radius: 999px; font-size: 0.85rem; border: 1px solid rgba(255, 255, 255, 0.25); }
.lang-btn:hover { border-color: var(--color-footer-text); }

/* THEME SWITCH (a site with a dark theme) */
.theme-switch { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.9rem; border-radius: 999px; border: 1px solid var(--color-switch-border); background: transparent; color: var(--color-switch-text); font: inherit; font-size: 0.85rem; font-weight: 500; cursor: pointer; transition: border-color 0.2s, color 0.2s; }
.theme-switch:hover { border-color: var(--color-primary); color: var(--color-text); }

/* LESS MOTION, for a visitor who asked their system for it */
@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    * { transition: none !important; }
}

/* PHONE (a screen up to 40rem): the menu scrolls with the page and wraps, its links taking the room left; buttons take the whole width */
@media (max-width: 40rem) {
    .site-nav { position: static; padding: 0.75rem 1rem; gap: 0.5rem 1rem; }
    .nav-links { flex: 1 1 auto; margin-left: 0; gap: 0.25rem 1.25rem; }
    .hero { padding: 2.25rem 1rem 2.5rem; }
    .actions .btn { flex: 1 1 100%; }
    .section { padding: 2.5rem 1rem; }
    .session-when { flex-basis: 100%; }
    .join-band { padding: 2.5rem 1rem; }
    .page-head { padding: 2.5rem 1rem 0.5rem; }
    .site-footer { padding: 2rem 1rem 1rem; }
}
